function validate([left, right]) {
  if (!Number.isInteger(left) || !Number.isInteger(right)) return 'left and right must be integers.';
  if (left < 1 || right > 10000) return 'left and right are between 1 and 10^4.';
  if (left > right) return 'left must not be greater than right.';
  return null;
}

