function selfDividingNumbers(left, right) {
  const result = [];
  for (let n = left; n <= right; n++) {
    let rest = n;
    let ok = true;
    while (rest > 0) {
      const digit = rest % 10;
      if (digit === 0 || n % digit !== 0) {
        ok = false;
        break;
      }
      rest = Math.floor(rest / 10);
    }
    if (ok) {
      result.push(n);
    }
  }
  return result;
}

