function selfDividingNumbers(left, right) {
  const out = [];
  for (let x = left; x <= right; x++) {
    const digits = String(x).split('').map(Number);
    if (digits.every(d => d !== 0 && x % d === 0)) out.push(x);
  }
  return out;
}

